LESSONS=(
Lesson(166,'Lesson_166-from-a-business-question-to-a-metric-contract','From a Business Question to a Metric Contract','54-business-question-to-metric-contract.md','wiki.semantic-layer.metric-contract','Một câu hỏi nghiệp vụ phải được chốt thành sáu quyết định nào để hai người cài độc lập tạo cùng tập bản ghi và cùng con số?',(F,D,K),(FL,DL,KL),(
('Vì sao tên chỉ số chưa phải định nghĩa','Câu “doanh thu tháng trước” còn thiếu đối tượng được tính, loại doanh thu, mốc thời gian, ranh giới kỳ, loại trừ, currency và cách gộp. Hai query đều đúng SQL có thể cho số khác mà không query nào tự báo lỗi. Metric contract biến tranh luận về con số thành sáu quyết định có owner và phép kiểm. Contract không phải đoạn mô tả marketing; nó phải đủ chính xác để người khác dựng executable logic mà không hỏi tác giả.'),
('Phần một: population','Population mô tả universe bản ghi đủ điều kiện trước khi tính: loại giao dịch, trạng thái, product/channel/region, entity identity, nguồn được phép và coverage period. Ghi cả inclusion lẫn exclusion. Cancelled order, test account, internal transfer, fraudulent transaction, tax, refund và chargeback phải có disposition. Population là intrinsic semantics; filter do người dùng chọn như region=`North` là query parameter, không được lẫn vào định nghĩa trừ khi metric thực sự chỉ dành cho North.'),
('Phần hai và ba: grain, time','Grain nêu một observation ở mức nào trước aggregate: order, order line, invoice line, payment hay recognized-revenue event. Metric grain nêu kết quả theo entity/time grain nào và khả năng slice hợp lệ. Time contract chỉ rõ timestamp role dùng để quy kỳ, timezone, calendar/fiscal period, cutoff và late-data/restatement. `created_at`, `paid_at`, `shipped_at` và `recognized_at` trả lời bốn câu khác nhau; chọn mốc phải theo business event chứ không theo cột tiện nhất.'),
('Phần bốn và năm: filters, aggregation','Intrinsic filter là điều kiện luôn thuộc definition, như exclude test orders; user filter là dimension người hỏi có thể thay đổi mà không đổi identity của metric. Aggregation contract ghi base expression, operator, grouping, additivity, unit, null/zero policy và numerator/denominator nếu là ratio. Với gross margin, phải sum gross profit và revenue ở target grain rồi divide; average của row-level percentages hoặc sum ratios không bảo toàn nghĩa.'),
('Phần sáu: ownership và change','Owner có quyền nghiệp vụ phê duyệt meaning, không nhất thiết là người viết SQL. Contract cần metric ID, version, effective date, steward/technical owner, approver, change reason, compatibility và consumers. Thay filter/refund/time role có thể là breaking semantic change dù tên cột không đổi. Version mới cần parallel run, semantic diff, communication và deprecation; không overwrite definition cũ rồi sửa lịch sử dashboard âm thầm.'),
('Tám cách hiểu của một câu hỏi','Để tạo tám cách hiểu có kiểm soát, chọn ba quyết định nhị phân thật sự độc lập: gross hay net; order date hay recognized date; booked hay completed population. Tổ hợp tạo tám contracts, mỗi contract có tên riêng và query riêng. Đây là bài tập phơi bày ambiguity, không phải khẳng định mọi câu hỏi luôn có đúng tám nghĩa. Nếu các trục phụ thuộc nhau hoặc có nhiều hơn hai lựa chọn, số cách hiểu thay đổi.'),
('Phép thử hai implementation','Khóa cùng source snapshot, cutoff và contract version; hai người không trao đổi query. So compiled SQL/logic, eligible-row set, numerator, denominator, time buckets và final values. Chỉ so con số cuối có thể che hai lỗi triệt tiêu nhau. Nếu khác, phân loại defect: contract mơ hồ, dữ liệu/engine khác, implementation sai hoặc rounding. Sửa contract trước retest; không hướng dẫn miệng vì knowledge ngoài contract làm phép thử mất ý nghĩa.'),
),('population phải ghi inclusion và exclusion','grain phải mô tả observation trước aggregate','metric output grain khác source row grain','time role phải gắn business event','timezone và fiscal calendar thuộc contract','intrinsic filter khác user-selected filter','aggregation phải ghi operator theo dimension','ratio cần numerator và denominator','null và divide-by-zero policy phải rõ','currency và unit phải được quản trị','owner phê duyệt meaning không chỉ SQL','semantic change cần version và effective date','hai implementation dùng cùng snapshot/cutoff','eligible-row diff quan trọng hơn chỉ final value','tám cách hiểu là tổ hợp của các trục đã công bố')),
Lesson(167,'Lesson_167-the-semantic-graph-entities-dimensions-measures-metrics','The Semantic Graph - Entities, Dimensions, Measures and Metrics','55-semantic-graph-entities-dimensions-measures-metrics.md','wiki.semantic-layer.semantic-graph','Đồ thị ngữ nghĩa biểu diễn entity, dimension, measure, metric và đường join như thế nào để máy xác định được một câu hỏi có hợp lệ hay mơ hồ?',(D,K,F),(DL,KL,FL),(
('Đồ thị thay cho danh sách khai báo','Semantic model cần trả lời reachability: metric nào có thể group/filter theo dimension nào, hai metrics có chung grouping grain không, và join path nào hợp lệ. Danh sách fields không mã hóa được các câu hỏi này. Trong đồ thị, semantic models/entities là nodes hoặc anchors, relationships là edges có direction/cardinality; metrics phụ thuộc base aggregations và dimensions gắn với entity context. Query planner duyệt graph dưới constraints thay vì nối mọi bảng có cột trùng tên.'),
('Entity và identity','Entity là đối tượng có identity dùng để nối semantic models: order, customer, product, account. Cần phân biệt primary, foreign và unique roles, namespace, business key/canonical key và temporal validity. Entity không đồng nhất với physical table: một table có thể chứa order và customer identifiers; một customer entity có thể được mô tả bởi nhiều tables. Nếu identity không ổn định hoặc many-to-many mapping không được mô hình hóa, graph hợp lệ cú pháp vẫn cho duplicate hoặc ambiguous traversal.'),
('Dimension và scope','Dimension là thuộc tính dùng để group, filter hoặc label metric; nó gắn với entity và semantic model nơi meaning được xác định. `status` của order khác `status` của customer. Time dimension cần timestamp role và granularity; categorical dimension cần domain/unknown policy; slowly changing attribute cần effective-time semantics. Fully qualified naming giúp phân biệt scope nhưng không sửa sai identity. Một dimension chỉ queryable với metric nếu có path hợp lệ không làm đổi grain trái contract.'),
('Measure và metric: khái niệm với cú pháp','Ở mức khái niệm, measure là đại lượng tại base grain cùng aggregation behavior; metric là named business calculation có population, time, filters, aggregation và owner. Product syntax có thể khác. Legacy MetricFlow từng khai báo measures riêng; đặc tả dbt mới đưa aggregation/expression vào simple metric và không còn measure node độc lập trong authoring spec. Giáo trình giữ distinction để reasoning, nhưng ví dụ code phải ghi version và không được trộn legacy với current YAML.'),
('Edges, cardinality và fanout','Mỗi relationship phải nêu join keys, one-to-one/one-to-many/many-to-one/many-to-many, direction và temporal condition nếu có. Đi từ fact-like node qua many-side rồi aggregate measure có thể fanout. Graph engine chỉ tự join an toàn khi cardinality và aggregation semantics cho phép. Many-to-many cần bridge/allocation hoặc query rewrite. Cardinality khai báo sai nguy hiểm hơn bỏ khai báo vì hệ thống có thể tự tin sinh SQL sai.'),
('Nhiều đường và path semantics','Customer có thể nối shipment trực tiếp qua recipient hoặc gián tiếp qua order purchaser. Hai paths cùng tới customer nhưng trả lời “người nhận” và “người mua”, không thể để planner chọn ngẫu nhiên. Graph phải dùng role names, path constraints hoặc metric-specific relationship. Cycle không tự là lỗi; ambiguity xuất hiện khi hai paths cùng syntactically valid nhưng khác business meaning/grain. Mỗi cặp multi-path cần câu hỏi và expected path làm test.'),
('Ba câu hỏi máy phải trả lời','Thứ nhất, metric X có thể slice theo dimension Y mà không fanout hay mất population không. Thứ hai, X và Z có thể đặt cạnh nhau ở common entity/time grain và cùng filter scope không. Thứ ba, nếu có nhiều paths, path nào được phép cho question/role hiện tại. Câu trả lời nên là executable validation hoặc explicit rejection kèm lý do, không phải silently generated SQL.'),
),('entity giữ identity và join role','dimension có scope theo entity context','measure có base grain và aggregation behavior','metric có business contract và owner','semantic graph không phải bản sao ERD','một table có thể chứa nhiều semantic entities','một entity có thể ánh xạ nhiều physical models','edge phải khai cardinality','many-side traversal có thể fanout','many-to-many cần bridge hoặc allocation semantics','qualified name không sửa identity sai','cycle không tự đồng nghĩa ambiguity','hai paths có thể biểu diễn hai business roles','co-query metrics cần common grain','current dbt syntax không được trộn legacy measure spec')),
Lesson(168,'Lesson_168-metric-types-simple-ratio-derived-and-cumulative','Metric Types - Simple, Ratio, Derived and Cumulative','56-metric-types-simple-ratio-derived-cumulative.md','wiki.semantic-layer.metric-types','Bốn loại metric khác nhau ở dependency, aggregation và time behavior nào, và phép kiểm nào phát hiện một implementation trông hợp lý nhưng sai khi roll up?',(D,K,W),(DL,KL,WL),(
('Simple metric','Simple metric áp một aggregation lên base expression ở declared grain: sum revenue, count orders, count-distinct customers, average duration. “Simple” chỉ nói dependency trực tiếp, không nói dễ gộp. `sum` của additive amount có thể roll up; average cần count/weight; count-distinct phải recompute/merge set or sketch; percentile không roll up từ percentile con. Contract vẫn cần population, time và dimensions được phép.'),
('Ratio metric','Ratio có numerator và denominator là hai metrics có compatible population, time grain, dimensions, unit và filter scope. Tính đúng là aggregate numerator và denominator ở requested grain rồi divide. Lưu row-level ratio hoặc average các group ratios cho sai khi denominators khác nhau. Division by zero, negative denominator, null, rounding và display percentage phải là policy. Test tối thiểu dùng hai nhóm có kích thước rất lệch để lỗi average-of-ratios lộ rõ.'),
('Derived metric','Derived metric là expression trên metrics khác: profit = revenue - cost; attainment = actual / target; year-over-year change = current/prior - 1. Nó kế thừa dependency, availability dimensions, time constraints, units và uncertainty của inputs. Hai input khác currency, population hoặc grain không tự compatible chỉ vì arithmetic chạy. Derived graph phải acyclic ở dependency level hoặc có cơ chế phát hiện cycle; rename/deprecation input cần impact analysis.'),
('Cumulative metric','Cumulative metric tích lũy input metric theo all-time, rolling window hoặc grain-to-date. Nó cần continuous time spine để kỳ không event vẫn tồn tại, clear window boundary, inclusive/exclusive rules, timezone và late-data policy. Running sum trên rows chỉ đúng nếu rows đã là dense period grain và không duplicate. Khi query ở grain khác default, cần re-aggregation policy như first/last/average tùy meaning; không sum các cumulative values.'),
('Phân loại theo computation graph','Hãy hỏi metric đọc trực tiếp base expression, chia hai metrics, kết hợp metrics hay thay đổi frame thời gian của một metric. Một metric có thể trông thuộc nhiều loại: rolling conversion rate là cumulative behavior áp lên ratio components; nên compute numerator/denominator trong windows rồi divide, không roll average conversion rates. Taxonomy là công cụ kiểm dependency và aggregation, không phải nhãn marketing.'),
('Đối chứng ba mức gộp','Tạo atomic dataset với hai stores, nhiều products và ba months; denominators lệch mạnh, có tháng rỗng. Tính ground truth từ rows tại store-product-month, rồi aggregate lên store-month, region-month và all-period. So implementation đúng với stored ratio/average ratio. Lưu absolute delta, relative delta và groups gây lỗi. Nếu hai cách vô tình bằng nhau trên balanced sample, fixture chưa đủ phân biệt.'),
('Ranh giới phiên bản và loại ngoài phạm vi','Tài liệu dbt hiện hành còn có conversion metric bên cạnh bốn loại trong roadmap. Bài này không phủ conversion-event matching, entity window và attribution. Cú pháp current/legacy khác nhau; note tập trung semantics chung. Không suy một engine hỗ trợ type name là nó tự đảm bảo population, identity, time hoặc business ownership đúng.'),
),('simple metric vẫn có thể non-additive','ratio phải giữ numerator denominator riêng','average of ratios sai khi weights khác','division by zero cần policy','derived metric kế thừa constraints của inputs','unit mismatch làm expression vô nghĩa','dependency cycle phải bị phát hiện','cumulative metric cần continuous time spine','rolling window cần boundary semantics','grain-to-date khác fixed rolling window','cumulative values không được sum lại','missing period là test bắt buộc','three-level rollup phải so atomic ground truth','conversion metric nằm ngoài bốn loại của bài','syntax version không thay semantic contract')),
Lesson(169,'Lesson_169-additivity-and-aggregation-in-the-semantic-layer','Additivity and Aggregation in the Semantic Layer','57-additivity-aggregation-semantic-layer.md','wiki.semantic-layer.additivity-enforcement','Tầng ngữ nghĩa phải mã hóa additivity như thế nào để từ chối hoặc rewrite truy vấn sai mà không chặn nhầm các truy vấn hợp lệ?',(K,D,A),(KL,DL,AL),(
('Aggregation contract theo dimension','Additivity không phải thuộc tính boolean của cột. Sales amount có thể sum qua product/store/time nếu currency và grain đồng nhất; inventory balance sum qua product/store nhưng thường lấy last/average qua time; margin rate không sum qua bất kỳ chiều nào. Contract cần operator mặc định, dimensions cho phép, operator override theo dimension, unit/currency và behavior khi dimension không có trong query.'),
('Additive, semi-additive, non-additive','Additive measure roll up bằng associative operator trên disjoint partitions. Semi-additive measure có operator khác theo một chiều: balance có thể SUM across accounts nhưng LAST_NON_EMPTY across date. Non-additive ratio cần aggregate components; distinct count cần union/recompute/sketch; percentile cần distribution/sketch. Khai `SUM` mặc định cho mọi numeric field là lỗi modeling, không phải lỗi người dùng.'),
('Từ chối, rewrite hay tính lại','Semantic engine có ba phản ứng hợp lệ: reject query với diagnostic; rewrite xuống atomic grain rồi aggregate đúng; hoặc dùng state mergeable như numerator/denominator hay HLL sketch. Im lặng sum pre-aggregated distinct counts là không hợp lệ. Diagnostic cần nêu metric, requested dimensions, violated rule và alternative. Reject quá tay cũng là defect: query additive theo permitted dimensions phải chạy.'),
('Aggregate awareness','Pre-aggregate chỉ dùng nếu materialized grain chứa mọi requested dimensions/filters và stored state có thể re-aggregate đúng. Fully additive sums có thể roll up; average cần sum+count; ratio cần numerator+denominator; distinct needs mergeable sketch hoặc atomic IDs; last-value cần period boundary/state. Router phải semantic-diff aggregate table với atomic query trên fixture trước khi coi nó tương đương.'),
('Distinct count và chi phí','COUNT(DISTINCT entity) không cộng qua regions hoặc months nếu entity xuất hiện nhiều nhóm. Exact result cần scan/deduplicate at requested grain; approximate sketch giảm cost nhưng thêm error bound, seed/algorithm/version và merge compatibility. Đo wall time, bytes scanned, shuffle/memory và error ở ba grains. Không gọi approximate result là exact, và không dùng một benchmark warmed cache để kết luận chung.'),
('Negative tests và false positives','Bộ test gồm năm invalid queries: sum balance over time, sum rate, sum distinct counts, use incompatible aggregate, combine different units. Năm valid controls thay một điều kiện để chứng minh rule không chặn quá tay. Mỗi rejection cần stable error code. Nếu engine không thể reject, wrapper/lint/contract test phải bắt trước consumption; dashboard số sai không được coi là “trách nhiệm analyst”.'),
('Quan hệ với SQL engine','PostgreSQL mô tả mechanics của `sum`, `avg`, `count` và behavior trên empty set; SQL engine không biết business additivity. Semantic layer bổ sung constraint trên nghĩa và query shape. NULL result của aggregate trên tập rỗng, trừ count, phải được xử lý theo metric policy; `COALESCE(...,0)` chỉ đúng khi zero là observation hợp lệ chứ không phải missing/unknown.'),
),('additivity phải khai theo dimension','currency mismatch chặn sum dù cùng numeric type','balance cần time-specific aggregation','ratio phải aggregate components','distinct count không cộng qua overlapping groups','percentile cần raw distribution hoặc mergeable state','engine có thể reject rewrite hoặc recompute','diagnostic phải nêu violated rule','valid control query không được bị block','preaggregate phải chứa requested dimensions','average preaggregate cần sum và count','sketch cần error/version contract','empty-set null khác business zero','approximate không được gắn nhãn exact','aggregate router cần semantic equivalence test')),
Lesson(170,'Lesson_170-time-semantics-grain-offsets-and-period-comparison','Time Semantics - Grain, Offsets and Period Comparison','58-time-semantics-grain-offsets-period-comparison.md','wiki.semantic-layer.time-semantics','Metric time contract phải chốt timestamp role, grain, timezone và calendar như thế nào để period comparison đúng khi thiếu kỳ, khác độ dài tháng và qua năm nhuận?',(K,D,G),(KL,DL,GL),(
('Bốn quyết định thời gian','Mỗi metric phải chốt event timestamp role, default time grain, reference timezone và calendar/fiscal definition. Order date đo demand; ship date đo fulfillment; payment date đo cash; recognized date đo accounting revenue. Một record có nhiều clocks nên “theo tháng” chưa đủ. Default grain không cấm drill khác nhưng xác định display/aggregation behavior. Fiscal calendar có thể 4-4-5, week-based hoặc organization-specific và không suy từ Gregorian month.'),
('Timezone và ranh giới ngày','Timestamp cần biết instant và timezone policy. Giao dịch 00:30 UTC có thể thuộc ngày trước ở America/Los_Angeles và ngày hiện tại ở Asia/Ho_Chi_Minh. Convert sang business timezone trước date truncation; không cast UTC timestamp sang date rồi mới đổi timezone. Daylight-saving tạo ngày 23/25 giờ ở một số zones, nên rolling 24 hours khác calendar day. Lưu timezone database/version khi reproducibility quan trọng.'),
('Time spine và kỳ rỗng','Dense calendar/time spine tạo một row cho mọi period trong phạm vi rồi left join metrics. Nếu chỉ dùng periods xuất hiện trong fact, tháng rỗng biến mất; `lag(1)` lấy tháng có data trước đó thay vì tháng lịch trước. Calendar cần date, week/month/quarter/year keys, fiscal attributes, period start/end, working-day/holiday nếu relevant. `generate_series` dựng scaffold PostgreSQL, nhưng business calendar vẫn cần maintained dimensions và policy.'),
('Ba cách dịch kỳ','Có ít nhất ba semantics: calendar-coordinate offset, fixed-duration offset và aligned elapsed-position comparison. `2024-02-29 - 1 year` cần policy cho ngày không tồn tại; fixed 365 days không đồng nghĩa same date last year; month-to-date so với prior-month cùng số ngày elapsed khác full prior month. Chọn theo business question và document clipping/padding. Không áp một offset function cho mọi metric.'),
('Period-over-period và year-over-year','PoP cần current period, exact previous period trên dense spine và policy partial-period. YoY cần same fiscal/calendar coordinate, timezone và comparable coverage. Khi current month chưa kết thúc, so full previous month tạo bias; dùng aligned-to-date hoặc label incomplete. Leap-day có thể map Feb 29 sang Feb 28, Mar 1 hoặc exclude/separate; owner phải phê duyệt vì mỗi cách trả lời câu khác.'),
('Rolling window và period-to-date','Rolling N days là interval liên tục; rolling N calendar months có boundaries khác do month length; MTD/QTD/YTD reset theo calendar/fiscal start. Window inclusive endpoints có thể đếm thừa một ngày nếu dùng BETWEEN. Cumulative metric cần time spine, late-data restatement và re-aggregation policy khi query grain đổi. Running total qua rows chỉ đúng sau densification và deduplication ở target grain.'),
('Bộ fixture bắt lỗi','Dữ liệu kiểm phải có ba tháng rỗng, Feb 29, year boundary, midnight ở ít nhất hai timezones, partial current period và late event. Tính expected output bằng bảng tay độc lập cho ba metrics. So bucket membership trước values, vì cùng total có thể che phân kỳ sai. Lưu calendar version, timezone, cutoff, window endpoints và result diff; rerun cùng snapshot phải giống hệt.'),
),('timestamp role phải gắn business event','timezone conversion xảy ra trước date truncation','calendar day khác rolling 24 hours','default grain phải được công bố','fiscal calendar không suy từ Gregorian calendar','dense time spine giữ kỳ rỗng','lag trên sparse rows không phải previous calendar period','generate_series chỉ tạo scaffold','leap-day mapping cần owner policy','fixed 365-day offset khác one-year offset','partial-period comparison cần aligned coverage','rolling days khác rolling calendar months','window endpoints phải định nghĩa inclusive/exclusive','late event cần restatement policy','bucket-membership diff phải kiểm trước final totals')),
)

VERIFY={
166:'Khóa một snapshot và cutoff; hai người độc lập triển khai contract. So eligible-row IDs, buckets, numerator/denominator và result. Tạo tám contracts bằng ba trục nhị phân đã ghi, không chỉ liệt kê tám câu chữ.',
167:'Dựng graph từ mart, khai identity/cardinality và enumerate all paths. Với mỗi multi-path pair, chạy hai business questions có expected path khác nhau; kiểm fanout và common grain khi co-query metrics.',
168:'Tạo fixture denominators lệch và periods rỗng; tính atomic oracle rồi roll up ba grains. So simple, ratio, derived và cumulative implementations, dependency graph, window boundary và current-version compilation.',
169:'Khai mười measures/metrics; chạy năm invalid và năm valid controls. Lưu rejection codes hoặc rewritten SQL, semantic diff với atomic oracle và cost/error của exact so với approximate distinct.',
170:'Dựng dense calendar có fiscal fields, missing months, leap day, partial period và timezone boundary. So bucket membership cùng three offset semantics với hand-calculated oracle; rerun ở fixed cutoff.',
}

def fm(x):
    sources='\n'.join(f'  - {s}' for s in x.sources)
    return f'''---
note_id: {x.note_id}
note_type: concept-deep-dive
status: review
language: vi
created: 2026-10-01
last_verified: 2026-10-01
editorial_pass: humanized-v1
primary_question: {x.question}
source_ids:
{sources}
aliases: [{x.title}]
tags: [wiki/database-systems, semantic-layer, metrics, module-12]
reference_path: Material/DE/Reference/Library/Knowledge-Notes/PACK-DATABASE-MODELING-BOOK-01/{x.filename}
---
'''

def deep_note(x):
    parts=[fm(x),f'# {x.title}\n\n> [!abstract] Câu hỏi trung tâm\n> {x.question}\n']
    for i,(heading,body) in enumerate(x.core,1): parts.append(f'\n## {i}. {heading}\n\n{body}\n')
    parts.append('\n## 8. Ma trận kiểm chứng từng mệnh đề\n\nCác mệnh đề dưới đây phải được kiểm bằng fixture, invariant và output có thể chạy lại. Việc công cụ compile được YAML hoặc sinh SQL không tự chứng minh metric đúng nghĩa.\n')
    for i,probe in enumerate(x.probes,1):
        parts.append(f'''\n### 8.{i}. {probe}\n\n**Mệnh đề cần kiểm.** {probe}.\n\n**Cách kiểm.** {VERIFY[x.number]} Với mệnh đề này, ghi rõ dữ liệu phản ví dụ, expected result và failure signal. Tách validation cấu trúc khỏi xác nhận meaning của owner.\n\n**Bằng chứng đạt.** Lưu contract/graph, snapshot, query hoặc compiled SQL, output thô, semantic diff và assumptions. Chỉ đánh dấu đạt khi cùng artifact cho kết quả lặp lại ở cùng version/cutoff; nếu chưa chạy, đây là test protocol chứ chưa phải kết quả production.\n''')
    parts.append('''\n## 9. Quy trình phản biện\n\n1. Viết business question, population, grain, identity, time và unit trước syntax.\n2. Chỉ ra artifact canonical, owner, version và change process.\n3. Tách source fact, product-version detail và curriculum synthesis.\n4. Dựng normal case cùng phản ví dụ: denominator lệch, fanout, sparse period, timezone boundary hoặc non-additive rollup.\n5. So eligible rows và intermediate components trước final value; hai lỗi có thể triệt tiêu ở số cuối.\n6. Chạy negative tests song song với valid controls để phát hiện cả false negative và false positive.\n7. Lưu failed run, limitations và conditions khiến kết luận phải đổi.\n\n## 10. Câu hỏi tự kiểm tra\n\n1. Metric đang trả lời câu hỏi nào, trên population và grain nào?\n2. Entity/dimension nào reachable qua path nào, cardinality gì?\n3. Aggregation nào hợp lệ theo từng dimension và time grain?\n4. Ca biên nào cho kết quả hợp lệ cú pháp nhưng sai nghĩa?\n5. Chi tiết nào là khái niệm ổn định, chi tiết nào phụ thuộc phiên bản sản phẩm?\n6. Bằng chứng nào cho phép người khác bác bỏ implementation?\n\n## 11. Giới hạn và điều chưa cho phép kết luận\n\n- Chưa chạy lab hai người, semantic graph planner, ratio rollup, aggregation rejection hoặc calendar fixture; note mô tả protocol cần thực thi.\n- dbt/MetricFlow là ví dụ sản phẩm được kiểm ngày 2026-10-01; syntax và availability có thể đổi theo version/tier.\n- PostgreSQL documentation mô tả SQL mechanics, không tự cung cấp business semantics hay metric governance.\n- Kimball–Ross hỗ trợ grain, additivity và calendar modeling; semantic-layer enforcement là phần tổng hợp có đối chiếu tài liệu hiện hành.\n- Owner chưa phê duyệt meaning nên note giữ trạng thái `review`.\n''')
    refs='\n'.join(f'{i}. [[{s}]]' for i,s in enumerate(x.source_links,1))
    coverage='\n'.join(f'| [[{s}]] | Khái niệm, cơ chế, product detail hoặc SQL behavior liên quan | Đã đọc phạm vi có locator; không suy ngoài phạm vi |' for s in x.source_links)
    parts.append(f'''\n## Reference\n\n{refs}\n\n## Source coverage\n\n| Source slice | Nội dung sử dụng | Trạng thái |\n|---|---|---|\n{coverage}\n\n## Key takeaways\n\n- Metric contract bắt đầu từ population, grain, time, filters, aggregation và ownership; tên metric không đủ.\n- Semantic graph phải mã hóa identity, cardinality và path semantics để phát hiện fanout hoặc ambiguity.\n- Ratio, cumulative, distinct và semi-additive metrics cần state/behavior riêng; không roll up như số cộng được.\n- Time comparison đúng cần dense calendar, timezone, fiscal policy, partial-period và leap-day rules.\n- Chưa chạy protocol thì note là tài liệu học thuật có truy nguồn, không phải chứng nhận production.\n''')
    return ''.join(parts)

def folder(x): return BASE/x.directory
def field(text,name):
    match=re.search(rf'(?m)^\*\*{re.escape(name)}\.\*\*\s*(.+)$',text)
    if not match: raise ValueError(name)
    return match.group(1).strip()
def section(text,heading):
    match=re.search(rf'(?ms)^## {re.escape(heading)}\n\n(.*?)(?=^## |\Z)',text)
    if not match: raise ValueError(heading)
    return match.group(1).strip()
def contract(x):
    note=(folder(x)/'note.md').read_text(); after=(folder(x)/'after-note.md').read_text()
    if '**Outcome.**' in note: return tuple(field(note,k) for k in ('Outcome','Đánh giá','Lab','Pitfalls','Self-study (2,4 giờ)','Done when'))
    return (field(section(note,'Mục tiêu bài học'),'Năng lực cần chứng minh'),field(section(after,'Tiêu chí hoàn thành'),'Cách đánh giá'),field(section(after,'Thực hành'),'Nhiệm vụ'),field(section(after,'Bài làm sau buổi học'),'Lỗi cần chủ động loại trừ'),field(section(after,'Bài làm sau buổi học'),'Nhiệm vụ'),field(section(note,'Mục tiêu bài học'),'Điều kiện hoàn thành'))
def curriculum(x,knowledge):
    outcome,assessment,lab,pitfalls,homework,done=contract(x)
    header=f'# Phase 5: Modeling, Semantics and Analytical Product\n# Module 12: Semantic Layer and Metrics Engineering\n# Lesson {x.number}: {x.title}'
    body=re.sub(r'^---\n.*?\n---\n','',knowledge,flags=re.S); body=re.sub(r'^# .+\n+','',body,count=1)
    note=f'{header}\n\n## Mục tiêu bài học\n\n**Năng lực cần chứng minh.** {outcome}\n\n**Điều kiện hoàn thành.** {done}\n\n{body}'
    safety='Chỉ chạy metric fixtures, graph validation, semantic diff hoặc benchmark trên dataset thử nghiệm/versioned snapshot. Không sửa metric production, BI definitions hay calendar dùng chung để minh họa. Lưu input, version, cutoff, query/compiled SQL, raw output và diff.'
    questions='\n'.join(f'{i}. {q}' for i,q in enumerate(('Phát biểu population, grain, time và aggregation contract.','Nêu phản ví dụ cho kết quả hợp lệ cú pháp nhưng sai nghĩa.','Chỉ ra phần khái niệm ổn định và phần phụ thuộc phiên bản sản phẩm.','Đề xuất phép kiểm tái chạy được cùng valid control.'),1))
    after=f'{header}\n\n## Thực hành\n\n**Nhiệm vụ.** {lab}\n\n{safety}\n\n## Kiểm tra cuối bài\n\n{questions}\n\n## Tiêu chí hoàn thành\n\n**Cách đánh giá.** {assessment}\n\n**Điều kiện đạt.** {done}\n\n## Bài làm sau buổi học\n\n**Nhiệm vụ.** {homework}\n\n**Lỗi cần chủ động loại trừ.** {pitfalls}\n\n## Reference\n\n- Knowledge note: `{(PACK/x.filename).relative_to(ROOT)}`\n- Nội dung học thuật: `note.md` cùng thư mục.\n'
    return note,after

QUERIES={
166:['Metric contract sáu phần gồm gì?','Intrinsic filter khác user filter thế nào?','Hai implementation kiểm metric contract ra sao?'],
167:['Semantic graph khác ERD thế nào?','Measure khác metric ở mức khái niệm ra sao?','Nhiều join paths phải được kiểm thế nào?'],
168:['Bốn metric types khác nhau thế nào?','Vì sao ratio phải chia sau khi aggregate?','Cumulative metric cần time spine vì sao?'],
169:['Additivity được khai theo dimension ra sao?','Distinct count có dùng preaggregate được không?','Semantic layer nên reject hay rewrite invalid aggregation?'],
170:['Bốn quyết định time semantics là gì?','Sparse periods làm lag sai ra sao?','Leap day và partial period phải có policy nào?'],
}
def update_manifest(check=False):
    path=ROOT/'Docs/Second-Brain/second-brain-manifest.json'; data=json.loads(path.read_text()); ids={x.note_id for x in LESSONS}
    data['note_registry']=[n for n in data['note_registry'] if n.get('note_id') not in ids]; data['retrieval_test_set']=[q for q in data['retrieval_test_set'] if q.get('expected_note_id') not in ids]
    for x in LESSONS:
        data['note_registry'].append({'note_id':x.note_id,'path':f'2_Wiki/Database-Systems/{x.title}.md','status':'review','source_ids':list(x.sources),'last_verified':'2026-10-01'})
        data['retrieval_test_set'].extend({'query':q,'expected_note_id':x.note_id} for q in QUERIES[x.number])
    data['version']='1.0.33'; data['updated_at']='2026-10-01T23:58:00+07:00'; data['layers']['1_Nguon']['source_count']=len(data['source_registry']); data['layers']['2_Wiki']['note_count']=len(data['note_registry'])
    expected=json.dumps(data,ensure_ascii=False,indent=2)+'\n'
    if check: return [] if path.read_text()==expected else [str(path.relative_to(ROOT))]
    path.write_text(expected); return []
def main():
    parser=argparse.ArgumentParser(); parser.add_argument('--check',action='store_true'); args=parser.parse_args(); stale=[]
    for x in LESSONS:
        knowledge=normalize_markdown(deep_note(x)); note,after=curriculum(x,knowledge)
        for path,content in ((PACK/x.filename,knowledge),(WIKI/(x.title+'.md'),knowledge),(folder(x)/'note.md',note),(folder(x)/'after-note.md',after)):
            if args.check:
                if not path.exists() or path.read_text()!=content: stale.append(str(path.relative_to(ROOT)))
            else: path.write_text(content)
    stale.extend(update_manifest(args.check))
    if stale: print('STALE\n'+'\n'.join(stale)); return 1
    print(('checked' if args.check else 'written')+f'={len(LESSONS)*4} stale=0'); return 0
if __name__=='__main__': raise SystemExit(main())
